#!/usr/bin/env python3
"""Record actual image viewing and independently verify each prepared file."""
import fcntl,importlib.util,io
from pathlib import Path
from PIL import Image
s=importlib.util.spec_from_file_location('b',Path(__file__).with_name('continuous-warsaw-batch-000097.py'));b=importlib.util.module_from_spec(s);s.loader.exec_module(b);h=b.h;i=b.i
lock=(b.R/'worker.lock').open('a+');fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
observations={'443553': 'Original and derivative viewed. Full rectangular panel with gold-brown border, a church above two registers of figures, the Virgin and processional saints above, Roman Melodos below, and a bed scene lower right. All four outside board edges visible. Matches native IK 289; no tiny inscription transcription claimed.', '498525': 'Original and derivative viewed. Complete dark-bordered panel with two standing physician saints flanking a small red church and paired relic coffins, Christ medallion above. Full board and red/green perimeter retained. Matches IK 292. Source first-half nineteenth-century creation retained; reference to sixteenth/seventeenth-century stylistic models is not creation dating.', '498508': 'Original and derivative viewed, compared with existing native 498379 / IK 16 reproduction. IK 276 has a narrower raw wood panel, a notch at bottom, central Michael with rounded halo and a smaller face cloth; existing IK 16 has wider wings, differently posed and dressed figures and a broad dark painted border. Distinct inventories, dimensions (36.6 x 29.1 versus 34.5 x 30.3 cm), source images and physical wear support separate works. Full panel and white photographic surround preserved.', '498376': 'Original and derivative viewed. Complete supplied surviving painted oval panel with three standing patriarchs and ornate scroll-shaped carved polychrome surround. Full contour visible. Matches native IK 154 crowning element; counted once as this separately inventoried surviving element, not an entire iconostasis or three independent figures. Source seventeenth-century wording retained. Small 315 x 157 source image limits fine detail.', '498697': 'Original and derivative viewed. Complete panel with two standing long-bearded monks facing inward, scrolls in hands, Virgin and Child medallion above, gold field and brown outer border. All board edges visible. Matches IK 77. Probable Solovetsky monastery is a source place-of-production label, not a named maker; no fabricated artist identity. First half seventeenth-century source date retained.', '440339': 'Original and derivative viewed. Full broad panel with slightly curved top: standing Virgin extends a red/green mantle over kneeling clerics and rulers, gold patterned field and two dark inscriptions above. All supplied physical edges retained. Matches IK 152, distinct from the small multi-register Pokrow IK 289. Source circa 1740 remains circa, not exact.', '498329': 'Original and derivative viewed. Full rectangular panel with two registers: enthroned Virgin and surrounding prophets above, a row of standing saints below, ornamental perimeter. Board edges visible. Matches IK 11; one panel, no multiplication of scenes. Source eighteenth/nineteenth-century transition retained with conservative 1701-1900 bounds; no exact year invented.', '498506': 'Original and derivative viewed. Complete circular tondo showing white-haired Mark holding a book and pen, gold geometrical field, multicolored ornamental rim, white photographic surround. Entire circle retained without rectangular cropping. Matches IK 273. Wood, enamel and tempera source description preserved; no unseen reverse review claim.', '498691': 'Original and derivative viewed. Complete wooden panel with half-length frontal Anastasia in dark monastic habit, raised right hand and prayer ladder at left, silver field and brown border; a side projection remains visible. Matches IK 7. Provincial and probable Old Believer workshop qualifications retained; no tiny inscription claim.'}
files=[];decisions=[]
for r in i.selected(b.B)['rows']:
 im=h.load(i.folder(b.B)/'prepared'/(r['artwork_id']+'.json'));assert im['state']=='prepared';raw=Path(im['path']).read_bytes();orig=Path(im['original_path']).read_bytes();assert h.sha(raw)==im['sha256'] and h.sha(orig)==im['source_sha256'] and len(raw)==im['bytes']<=100000
 with Image.open(io.BytesIO(raw)) as pic:pic.load();assert pic.format=='JPEG' and pic.size==(im['width'],im['height'])
 with Image.open(io.BytesIO(orig)) as pic:pic.load();assert abs(pic.width/pic.height-im['width']/im['height'])<.03
 assert '/Documents/' not in im['original_path']
 decisions.append(dict(artwork_id=r['artwork_id'],source_id=r['native_id'],artist=r['creator_label'],sha256=im['sha256'],decision='accept',viewed_individually=True,viewed_path=im['path'],viewed_original_path=im['original_path'],original_sha256=im['source_sha256'],original_viewed_individually=True,tool='functions tools.view_image',observations=observations[r['native_id']],flag_resolution='Original and actual derivative individually viewed. The manual_visual_required switch conservatively flags the 315-pixel museum derivative, but the actual image is a complete authentic icon, not a placeholder. Full supplied frame, native inventory and source description match; no unseen reverse or tiny-inscription claim.',identity_confidence=.99,confidence_basis='Exact native object/image, inventory, dimensions, source description and observed physical composition; editorial judgment, not calibrated probability.'))
 files.append(dict(artwork_id=r['artwork_id'],sha256=im['sha256'],bytes=im['bytes'],complete_decode=True,proportions_preserved=True,original_sha256=im['source_sha256'],original_path=im['original_path']))
assert len(decisions)==9
review=dict(at=h.now(),batch_quality_decision='accept',reviewer='Codex actual image viewing',decisions=decisions,all_selected_files_individually_viewed=True,sample_only_files=[],limitations='Museum source images are 315 px wide. Compositions and complete supplied frames reviewed; no claim to inspect absent reverse views or tiny illegible inscriptions. All nine originals and all nine derivatives individually visually viewed, decoded and hashed. Native 498379 prior image also viewed to resolve a similar-subject version.')
h.save(i.folder(b.B)/'visual-review.json',review);b.save('actual-visual-review.json',review);b.save('prewrite-file-verification.json',dict(at=h.now(),files=files,plan_sha256=h.pinned(b.PHASE)[1]))
print('9 actual per-image visual decisions and complete file checks saved')
